layers.vertex:
attribute vec3 aO, aE; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU; vec3 arcAt(vec3 a, vec3 b, float f){ float e = sin(3.14159*f); return mix(a, b, f) + vec3(0., .16*sin(f*18.)*e + .35*e, 0.); }
    void main(){
      float u = uTime - aT - 0.10, L = length(aE - aO), tt = .875;
      if (u < 0. || u > tt){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(aE + vec3(0., .05, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.4;   /* no projectile: the eye opens in front of the target */
      float S = .5*(1. - pow(1. - clamp(u/.225, 0., 1.), 3.))*(1. + .25*smoothstep(tt - .19, tt, u));
      float c = cos(.12*sin(u*2.)), s = sin(.12*sin(u*2.)); vec2 q = mat2(c, -s, s, c)*position.xy;   // the eye stays level, only a slight rock
      mv.xy += q*S*1.25*(1. + .12*pow(max(sin(u*6.5), 0.), 10.)); vP = position.xy; vU = u; gl_Position = projectionMatrix*mv;
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU;
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){                                              /* Nightmare: a watching eye - slit pupil, jagged lashes, dripping light */
      vec2 p = vP; float r = length(p), a = atan(p.y, p.x);
      float beat = 1. + .7*pow(max(sin(vU*6.5), 0.), 10.);                                  /* heartbeat pulse */
      float fl = .85 + .15*sin(vU*47.)*sin(vU*31.);                                          /* nervous flicker */
      float eyeD = max(length(p - vec2(0., -.38)) - .6, length(p - vec2(0., .38)) - .6);
      float lid = exp(-pow(eyeD/.022, 2.)), fill = smoothstep(.02, -.04, eyeD)*.1;
      vec2 sp = p*vec2(1., .33); float slitD = length(sp) - .07;                              /* vertical slit pupil */
      float slit = exp(-pow(slitD/.012, 2.))*smoothstep(.02, -.04, eyeD);
      float iris = exp(-pow((r - .17)/.035, 2.))*.5*smoothstep(.02, -.04, eyeD);
      float lash = 0.;
      for (int i=0;i<9;i++){ float fi = float(i), x0 = -.44 + fi*.11, y0 = .2*(1. - x0*x0/.25) + .02;
        vec2 dir = normalize(vec2(x0*1.4, 1.)); vec2 q = p - vec2(x0, y0);
        float along = dot(q, dir), across = dot(q, vec2(-dir.y, dir.x)), L = .18 + .14*h1(fi) + .05*sin(vU*9. + fi*2.);
        lash += exp(-across*across/(.00012 + .0006*max(0., 1. - along/L)))*step(0., along)*smoothstep(L, L*.5, along); }
      float drip = 0.;
      for (int i=0;i<4;i++){ float fi = float(i), x0 = -.22 + fi*.15, y0 = -.2*(1. - x0*x0/.25);
        float L = .25 + .3*fract(vU*.6 + h1(fi + 3.)), q = p.x - x0, yy = y0 - p.y;
        drip += exp(-q*q/.00025)*step(0., yy)*smoothstep(L, L*.3, yy); }
      float halo = exp(-r*r*3.5)*.25;
      vec3 o = (uOrange*(lid*1.1 + fill + iris + lash*.9 + drip*.8 + halo) + mix(uGold, vec3(1.), .6)*(slit*1.6 + lid*.35 + lash*.3))*beat*fl*smoothstep(1., .88, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }
